#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    const char *input = (argc > 1) ? argv[1] : "";
    size_t len = strlen(input);
    char *stack = malloc(len);
    if (!stack) { perror("malloc"); return 1; }
    size_t sp = 0;
    int balanced = 1;
    for (size_t i = 0; i < len && balanced; ++i) {
        char c = input[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                stack[sp++] = c;
                break;
            case ')':
            case ']':
            case '}': {
                if (sp == 0) { balanced = 0; break; }
                char open = stack[--sp];
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    balanced = 0;
                }
                break;
            }
            default:
                break;
        }
    }
    if (sp != 0) balanced = 0;
    free(stack);
    puts(balanced ? "BALANCED" : "UNBALANCED");
    return 0;
}
